using System;using System.Drawing;using System.IO;using System.Windows.Forms;
namespace IDSketcher {
partial class Canvas {
 public void TestRotationGrip(){SelectGuide("Ellipse");EditGuide=true;Zoom=1;Offset=PointF.Empty;PointF c=Centre(),a=RotationHandle();float radius=StrokeSession.Distance(c,a);TestDrag(Point.Round(a),Point.Round(new PointF(c.X+radius,c.Y)));float angle=(EllipseRotation%360+360)%360;if(Math.Abs(angle-90)>2)throw new Exception("Drag rotation handle through 90 degrees");if(Doc.Selected.Image.GetPixel((int)c.X,(int)c.Y).A!=0)throw new Exception("Rotation grip must not paint");}
 public void TestStraightPreviewCancel(){ResetShift();BeginStraight(new PointF(10,10));OnMouseMove(new MouseEventArgs(MouseButtons.Left,0,200,180,0));if(Doc.Selected.Image.GetPixel(100,90).A!=0)throw new Exception("Straight preview must not paint");EndStroke();OnMouseUp(new MouseEventArgs(MouseButtons.Left,1,200,180,0));if(Doc.Selected.Image.GetPixel(100,90).A!=0)throw new Exception("Canceled straight drag must not paint");}
}
partial class Studio {
 public void TestLayerTypes(){SetDocument(new Document("A4",100),null);canvas.Zoom=1;canvas.Offset=PointF.Empty;canvas.TestRotationGrip();guideMode.SelectedItem="Freehand";canvas.SelectGuide("Freehand");canvas.TestStraightPreviewCancel();Layer pixels=canvas.Doc.Selected;AddTypedLayer(true);Layer vector=canvas.Doc.Selected;
  if(!vector.IsVector||sizeSlider.Visible||flowSlider.Visible||pressureMode.Visible||!vectorWeightSlider.Visible||canvas.VectorMode!="Select/edit")throw new Exception("Vector layer must show only vector tools");SelectTool("Eraser");if(canvas.VectorMode!="Select/edit")throw new Exception("Raster shortcuts on vector layer");canvas.TestRightClick();if(brushPopup!=null&&brushPopup.Visible)throw new Exception("No brush popup on vector layer");
  vectorMode.SelectedItem="Line";canvas.TestDrag(new Point(50,50),new Point(200,50));if(vector.Vectors.Count!=1||vector.Image.GetPixel(100,50).A!=0)throw new Exception("Vector layer stores geometry only");
  canvas.Doc.Active=0;RefreshLayers();if(!sizeSlider.Visible||vectorWeightSlider.Visible||canvas.VectorMode!="Brushes")throw new Exception("Pixel layer tools restore");SelectTool("Pen");canvas.TestColourStroke();if(pixels.Image.GetPixel(100,50).A==0||pixels.Vectors.Count!=0)throw new Exception("Pixel layer draws pixels only");
  string path=Path.Combine(Path.GetTempPath(),Guid.NewGuid()+".idsk");try{canvas.Doc.Save(path);using(var loaded=Document.Load(path))if(loaded.Layers[0].IsVector||!loaded.Layers[1].IsVector||loaded.Layers[1].Vectors.Count!=1)throw new Exception("Layer types persist");}finally{if(File.Exists(path))File.Delete(path);}
  // Version 2 used mixed layers; migrate the raster and editable objects into a pair.
  path=Path.Combine(Path.GetTempPath(),Guid.NewGuid()+".idsk");try{using(var w=new BinaryWriter(File.Create(path))){w.Write("IDSKETCHER2");w.Write("A4");w.Write(100);w.Write(canvas.Doc.Width);w.Write(canvas.Doc.Height);w.Write(0);w.Write(1);w.Write("Old mixed");w.Write(1f);w.Write(true);byte[] png=Document.Png(pixels.Image);w.Write(png.Length);w.Write(png);w.Write(1);var v=vector.Vectors[0];w.Write(v.Kind);w.Write(v.Colour.ToArgb());w.Write(v.Width);w.Write(v.Opacity);w.Write(v.Points.Count);foreach(var point in v.Points){w.Write(point.X);w.Write(point.Y);}}using(var loaded=Document.Load(path)){if(loaded.Layers.Count!=2||loaded.Layers[0].IsVector||!loaded.Layers[1].IsVector||loaded.Layers[0].Image.GetPixel(100,50).A==0||loaded.Layers[1].Vectors.Count!=1)throw new Exception("Mixed project migration");loaded.Save(path);}using(var loaded=Document.Load(path))if(!loaded.Layers[1].IsVector)throw new Exception("Migrated project reopens");}finally{if(File.Exists(path))File.Delete(path);}dirty=false;
 }
}
}
